<?php

declare(strict_types=1);

namespace App\Policies;

use Illuminate\Auth\Access\HandlesAuthorization;
use Illuminate\Foundation\Auth\User as AuthUser;
use Spatie\Permission\Models\Role;

/**
 * Filament Shield policy for Role. Generated by `php artisan shield:generate`;
 * each ability maps to a "{Action}:Role" permission seeded by RoleSeeder.
 * super_admin bypasses these checks (Gate::before in Shield).
 *
 * Regenerating policies with shield:generate may overwrite these docblocks.
 */
class RolePolicy
{
    use HandlesAuthorization;

    /**
     * Determine whether the admin may list roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ViewAny:Role" permission.
     */
    public function viewAny(AuthUser $authUser): bool
    {
        return $authUser->can('ViewAny:Role');
    }

    /**
     * Determine whether the admin may view one roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "View:Role" permission.
     */
    public function view(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('View:Role');
    }

    /**
     * Determine whether the admin may create roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Create:Role" permission.
     */
    public function create(AuthUser $authUser): bool
    {
        return $authUser->can('Create:Role');
    }

    /**
     * Determine whether the admin may edit roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "Update:Role" permission.
     */
    public function update(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('Update:Role');
    }

    /**
     * Determine whether the admin may delete one roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "Delete:Role" permission.
     */
    public function delete(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('Delete:Role');
    }

    /**
     * Determine whether the admin may bulk delete roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "DeleteAny:Role" permission.
     */
    public function deleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('DeleteAny:Role');
    }

    /**
     * Determine whether the admin may restore one soft-deleted roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "Restore:Role" permission.
     */
    public function restore(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('Restore:Role');
    }

    /**
     * Determine whether the admin may permanently delete one roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "ForceDelete:Role" permission.
     */
    public function forceDelete(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('ForceDelete:Role');
    }

    /**
     * Determine whether the admin may permanently bulk delete roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "ForceDeleteAny:Role" permission.
     */
    public function forceDeleteAny(AuthUser $authUser): bool
    {
        return $authUser->can('ForceDeleteAny:Role');
    }

    /**
     * Determine whether the admin may bulk restore soft-deleted roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "RestoreAny:Role" permission.
     */
    public function restoreAny(AuthUser $authUser): bool
    {
        return $authUser->can('RestoreAny:Role');
    }

    /**
     * Determine whether the admin may duplicate roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @param  Role  $role  The record being authorized.
     * @return bool True when the admin holds the "Replicate:Role" permission.
     */
    public function replicate(AuthUser $authUser, Role $role): bool
    {
        return $authUser->can('Replicate:Role');
    }

    /**
     * Determine whether the admin may reorder roles.
     *
     * @param  AuthUser  $authUser  The signed-in admin.
     * @return bool True when the admin holds the "Reorder:Role" permission.
     */
    public function reorder(AuthUser $authUser): bool
    {
        return $authUser->can('Reorder:Role');
    }
}
